package com.fitnutri.backend.records;

import com.fasterxml.jackson.databind.*;
import com.fitnutri.backend.foodreference.ReferenceImportService;
import com.fitnutri.backend.support.TestDatabase;
import com.fitnutri.backend.user.UserRepository;
import com.fitnutri.backend.submission.SubmissionReceiptRepository;
import java.net.*;
import java.net.http.*;
import java.nio.file.Path;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.server.LocalServerPort;
import org.springframework.core.io.*;
import org.springframework.test.context.*;
import static org.junit.jupiter.api.Assertions.*;

/** Actual official source -> HTTP search/preview -> reviewed input -> atomic PG save and receipt. No frontend/E2E claim. */
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT) @ActiveProfiles("integration-test") @TestInstance(TestInstance.Lifecycle.PER_CLASS)
class FoodRecordingHttpIntegrationTest {
    private static final TestDatabase DB=TestDatabase.create();static{Runtime.getRuntime().addShutdownHook(new Thread(DB::close));}
    @DynamicPropertySource static void db(DynamicPropertyRegistry r){r.add("spring.datasource.url",DB::url);r.add("spring.datasource.username",DB::username);r.add("spring.datasource.password",DB::password);}
    @LocalServerPort int port;@Autowired ReferenceImportService importer;@Autowired UserRepository users;@Autowired FoodRecordRepository foods;@Autowired SubmissionReceiptRepository receipts;@Autowired com.fitnutri.backend.foodreference.FoodReferenceRepository references;
    private final ObjectMapper json=new ObjectMapper();private HttpClient client;private String csrf,email;
    @BeforeAll void verifiedOfficialCatalogue() throws Exception {
        Path dir=Path.of(System.getenv().getOrDefault("TEST_REFERENCE_SOURCE_DIR",Path.of("..",".local","reference-sources").toString())).toAbsolutePath().normalize();Map<String,Resource> raw=new HashMap<>();for(String name:List.of("ausnut-2023-food-details.xlsx","ausnut-2023-food-nutrient-profiles.xlsx","ausnut-2023-list-of-nutrients.xlsx"))raw.put(name,new FileSystemResource(dir.resolve(name)));assertEquals(3741,importer.importManifest(new ClassPathResource("data/manifests/ausnut-2023-r1.json"),new ClassPathResource("data/ausnut-2023-foods-r1.json"),raw).importedCount());
    }
    @BeforeEach void signedInAdult() throws Exception {
        client=HttpClient.newBuilder().cookieHandler(new CookieManager(null,CookiePolicy.ACCEPT_ALL)).build();csrf=null;email="http-food-"+UUID.randomUUID()+"@example.test";csrf=status(200,send("GET","/api/auth/csrf",null)).get("token").asText();status(201,send("POST","/api/auth/register",Map.of("email",email,"password","Synthetic123","displayName","Synthetic HTTP food")));status(200,send("POST","/api/auth/login",Map.of("email",email,"password","Synthetic123")));csrf=status(200,send("GET","/api/auth/csrf",null)).get("token").asText();var profile=status(200,send("GET","/api/profile",null));var setup=new LinkedHashMap<String,Object>();setup.put("expectedUserVersion",profile.get("user").get("version").asLong());setup.put("expectedProfileVersion",null);setup.put("displayName","Synthetic HTTP food");setup.put("birthYear",1990);setup.put("adultConfirmed",true);setup.put("sex","PREFER_NOT_TO_SAY");setup.put("heightCm",170);setup.put("activityLevel","LIGHT");setup.put("goalType",null);setup.put("dailyTargetKj",null);setup.put("energyUnit","KJ");setup.put("healthSafetyAnswer","NO");setup.put("qaConsentGranted",false);setup.put("zone","Australia/Sydney");setup.put("initialWeight",Map.of("recordDate","2020-01-01","weightKg",70));status(200,send("POST","/api/profile/onboarding",setup));
    }
    private HttpResponse<String> send(String method,String path,Object body) throws Exception {var r=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+path));if(csrf!=null)r.header("X-CSRF-TOKEN",csrf);if(body!=null)r.header("Content-Type","application/json");return client.send(r.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body))).build(),HttpResponse.BodyHandlers.ofString());}
    private JsonNode status(int expected,HttpResponse<String> r) throws Exception {assertEquals(expected,r.statusCode(),r.body());return json.readTree(r.body());}
    private Map<String,Object> item(String reference,int grams,String meal){return new LinkedHashMap<>(Map.of("clientEntryId",UUID.randomUUID().toString(),"referenceId",reference,"quantityGrams",grams,"mealType",meal));}
    private Map<String,Object> batch(List<Map<String,Object>> items){return new LinkedHashMap<>(Map.of("submissionId",UUID.randomUUID().toString(),"recordDate","2020-01-02","zone","Australia/Sydney","source","MANUAL","items",items));}
    private Long owner(){return users.findByCanonicalEmail(email).orElseThrow().getId();}
    @Test void officialSearchPreviewTwoMealsSaveAndUnknownOutcomeReceiptReplayUseActualSessionAndPostgres() throws Exception {
        var results=status(200,send("GET","/api/food-reference/search?query=rice%20cooked&size=2",null));assertEquals(2,results.get("results").size());assertTrue(results.get("results").get(0).get("referenceId").isTextual());String rice=status(200,send("GET","/api/food-reference/F007661",null)).get("referenceId").asText();var preview=status(200,send("GET","/api/food-reference/by-id/"+rice+"/nutrition?grams=150",null));assertEquals(988.5,preview.get("nutrients").get("energyKj").asDouble());assertTrue(preview.get("reference").get("dataset").get("verified").asBoolean());
        var request=batch(List.of(item(rice,150,"LUNCH"),item(rice,200,"DINNER")));var response=send("POST","/api/records/food/batch",request);var saved=status(201,response);assertFalse(saved.get("replayed").asBoolean());assertEquals(2,saved.get("records").size());assertEquals("no-store",response.headers().firstValue("Cache-Control").orElseThrow());var proof=status(200,send("GET","/api/submissions/"+request.get("submissionId"),null));assertEquals(saved.get("records"),proof.get("records"));var replay=status(200,send("POST","/api/records/food/batch",request));assertTrue(replay.get("replayed").asBoolean());assertEquals(saved.get("records"),replay.get("records"));var rows=foods.findByUserIdOrderByRecordedAtDesc(owner());assertEquals(2,rows.size());assertEquals(new java.math.BigDecimal("2306.500"),rows.stream().map(FoodRecord::getEnergyKj).reduce(java.math.BigDecimal.ZERO,java.math.BigDecimal::add));assertTrue(rows.stream().allMatch(r->r.getDataQuality()==DataQuality.CURRENT));
        var listed=status(200,send("GET","/api/records/food?from=2020-01-02&to=2020-01-02&zone=UTC",null));assertEquals(2,listed.size());assertTrue(listed.get(0).get("id").isTextual());assertEquals("2020-01-02",listed.get(0).get("recordDate").asText());assertTrue(listed.get(0).get("reference").get("dataset").get("verified").asBoolean());var detail=status(200,send("GET","/api/records/food/"+listed.get(0).get("id").asText(),null));assertEquals(listed.get(0),detail);assertFalse(detail.has("calories"));assertFalse(detail.has("userId"));assertEquals(1,status(200,send("GET","/api/records/food?from=2020-01-02&to=2020-01-02&mealType=LUNCH",null)).size());assertEquals(0,status(200,send("GET","/api/records/food?from=2020-01-03&to=2020-01-03",null)).size());
    }
    @Test void oldProtocolAndTamperedAuthorityAre400AndNoReceiptOrRecordAppears() throws Exception {
        String rice=status(200,send("GET","/api/food-reference/F007661",null)).get("referenceId").asText();var part=item(rice,100,"LUNCH");part.put("calories",1);var request=batch(List.of(part));assertEquals("VALIDATION_ERROR",status(400,send("POST","/api/records/food/batch",request)).get("code").asText());assertTrue(receipts.findByUserIdAndSubmissionId(owner(),UUID.fromString((String)request.get("submissionId"))).isEmpty());status(400,send("POST","/api/records/food",Map.of("foodName","Forged authority","quantityGrams",100,"mealType","LUNCH","source","MANUAL","calories",1)));assertTrue(foods.findByUserIdOrderByRecordedAtDesc(owner()).isEmpty());
    }
    @Test void canonicalSingleAdapterReplaysAsBatchAndBadSecondReferenceLeavesNoPartialMeal() throws Exception {
        String rice=status(200,send("GET","/api/food-reference/F007661",null)).get("referenceId").asText();var part=item(rice,100,"SNACK");var request=batch(List.of(part));var single=new LinkedHashMap<>(request);single.remove("items");single.putAll(part);var saved=status(201,send("POST","/api/records/food",single));var replay=status(200,send("POST","/api/records/food/batch",request));assertEquals(saved.get("records"),replay.get("records"));var bad=batch(List.of(item(rice,150,"LUNCH"),item("999999999",200,"DINNER")));var error=status(404,send("POST","/api/records/food/batch",bad));assertEquals("referenceId",error.get("fieldErrors").get(0).get("field").asText());assertEquals(((List<?>)bad.get("items")).get(1) instanceof Map<?,?> m?m.get("clientEntryId"):null,error.get("fieldErrors").get(0).get("clientEntryId").asText());assertEquals(1,foods.findByUserIdOrderByRecordedAtDesc(owner()).size());assertTrue(receipts.findByUserIdAndSubmissionId(owner(),UUID.fromString((String)bad.get("submissionId"))).isEmpty());
    }
    @Test void detailAndDateRangeAreOwnedAndMissingOrInvalidBoundsAre400() throws Exception {
        String rice=status(200,send("GET","/api/food-reference/F007661",null)).get("referenceId").asText();var proof=status(201,send("POST","/api/records/food/batch",batch(List.of(item(rice,100,"LUNCH")))));String id=proof.get("records").get(0).get("id").asText();status(200,send("GET","/api/records/food/"+id,null));
        signedInAdult();assertEquals("NOT_FOUND",status(404,send("GET","/api/records/food/"+id,null)).get("code").asText());assertEquals("NOT_FOUND",status(404,send("GET","/api/records/food/999999999",null)).get("code").asText());assertEquals(0,status(200,send("GET","/api/records/food?from=2020-01-02&to=2020-01-02",null)).size());status(400,send("GET","/api/records/food?from=2020-01-02",null));status(400,send("GET","/api/records/food?from=2020-01-03&to=2020-01-01",null));
    }
    @Test void correctionNoOpStaleVersionAndSoftDeleteRetainOriginalCreationProof() throws Exception {
        String ref=status(200,send("GET","/api/food-reference/F007661",null)).get("referenceId").asText();var original=batch(List.of(item(ref,100,"LUNCH")));original.put("source","IMAGE");var proof=status(201,send("POST","/api/records/food/batch",original));String id=proof.get("records").get(0).get("id").asText();var update=new LinkedHashMap<String,Object>(Map.of("expectedVersion",0,"referenceId",ref,"quantityGrams",150,"mealType","DINNER","recordDate","2020-01-03","zone","Australia/Sydney"));var changed=status(200,send("PUT","/api/records/food/"+id,update));assertEquals(1,changed.get("version").asInt());assertEquals(988.5,changed.get("nutrients").get("energyKj").asDouble());assertEquals("IMAGE",changed.get("source").asText());assertEquals("VERSION_CONFLICT",status(409,send("PUT","/api/records/food/"+id,update)).get("code").asText());update.put("expectedVersion",1);var noop=status(200,send("PUT","/api/records/food/"+id,update));assertEquals(changed,noop);status(409,send("DELETE","/api/records/food/"+id+"?expectedVersion=0",null));assertEquals(204,send("DELETE","/api/records/food/"+id+"?expectedVersion=1",null).statusCode());status(404,send("GET","/api/records/food/"+id,null));assertEquals(204,send("DELETE","/api/records/food/"+id+"?expectedVersion=1",null).statusCode());assertEquals(proof.get("records"),status(200,send("POST","/api/records/food/batch",original)).get("records"));assertNotNull(foods.findById(Long.valueOf(id)).orElseThrow().getDeletedAt());
    }
    @Test void inactiveOriginalPreviewAndCorrectionAreOwnedExceptionsAndCannotAuthorizeNewCreation() throws Exception {
        String ref=status(200,send("GET","/api/food-reference/F007661",null)).get("referenceId").asText();var proof=status(201,send("POST","/api/records/food/batch",batch(List.of(item(ref,100,"LUNCH")))));String id=proof.get("records").get(0).get("id").asText();var source=references.findById(Long.valueOf(ref)).orElseThrow();source.setActive(false);references.saveAndFlush(source);
        try {status(409,send("GET","/api/food-reference/by-id/"+ref+"/nutrition?grams=150",null));var p=status(200,send("GET","/api/food-reference/by-id/"+ref+"/nutrition?grams=150&recordId="+id,null));assertFalse(p.get("reference").get("active").asBoolean());assertEquals(988.5,p.get("nutrients").get("energyKj").asDouble());var body=Map.of("expectedVersion",0,"referenceId",ref,"quantityGrams",150,"mealType","LUNCH","recordDate","2020-01-02","zone","Australia/Sydney");status(200,send("PUT","/api/records/food/"+id,body));assertEquals("REFERENCE_INACTIVE",status(409,send("POST","/api/records/food/batch",batch(List.of(item(ref,150,"SNACK"))))).get("code").asText());signedInAdult();assertEquals("NOT_FOUND",status(404,send("GET","/api/food-reference/by-id/"+ref+"/nutrition?grams=150&recordId="+id,null)).get("code").asText());}
        finally {source.setActive(true);references.saveAndFlush(source);}
    }
}
